const listApplications = `-- name: ListApplications :many
SELECT id, tenant_id, app_number, applicant_name, entity_type, applicant_segment, loan_amount, tenure_months, assigned_officer_id, stage, status, progress_percentage, bfs_score, risk_tier, recommendation, created_by, created_at, updated_at, is_archived, archived_at, archived_by, archive_reason FROM applications
WHERE tenant_id = $1
  AND ($2::text = '' OR app_number ILIKE '%' || $2 || '%' OR applicant_name ILIKE '%' || $2 || '%')
  AND (NULLIF($3::text, '')::application_stage IS NULL OR stage = NULLIF($3::text, '')::application_stage)
  AND (NULLIF($4::text, '')::application_status IS NULL OR status = NULLIF($4::text, '')::application_status)
  AND (NULLIF($5::text, '')::entity_type IS NULL OR entity_type = NULLIF($5::text, '')::entity_type)
  AND (NULLIF($6::text, '')::uuid IS NULL OR assigned_officer_id = NULLIF($6::text, '')::uuid)
  AND (
    $7::text = 'all' OR
    ($7::text = 'true' AND is_archived = TRUE) OR
    (($7::text = 'false' OR $7::text = '') AND is_archived = FALSE)
  )
ORDER BY created_at DESC
LIMIT $9 OFFSET $8
`

type ListApplicationsParams struct {
	TenantID          pgtype.UUID `json:"tenant_id"`
	Search            string      `json:"search"`
	Stage             string      `json:"stage"`
	Status            string      `json:"status"`
	EntityType        string      `json:"entity_type"`
	AssignedOfficerID string      `json:"assigned_officer_id"`
	ArchivedFilter    string      `json:"archived_filter"`
	OffsetVal         int32       `json:"offset_val"`
	LimitVal          int32       `json:"limit_val"`
}

func (q *Queries) ListApplications(ctx context.Context, arg ListApplicationsParams) ([]Application, error) {
	rows, err := q.db.Query(ctx, listApplications,
		arg.TenantID,
		arg.Search,
		arg.Stage,
		arg.Status,
		arg.EntityType,
		arg.AssignedOfficerID,
		arg.ArchivedFilter,
		arg.OffsetVal,
		arg.LimitVal,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Application
	for rows.Next() {
		var i Application
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.AppNumber,
			&i.ApplicantName,
			&i.EntityType,
			&i.ApplicantSegment,
			&i.LoanAmount,
			&i.TenureMonths,
			&i.AssignedOfficerID,
			&i.Stage,
			&i.Status,
			&i.ProgressPercentage,
			&i.BfsScore,
			&i.RiskTier,
			&i.Recommendation,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.IsArchived,
			&i.ArchivedAt,
			&i.ArchivedBy,
			&i.ArchiveReason,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

